package com.metabuild.modules.admin.departments.controller;
import com.metabuild.admin.api.security.RequiresPermissions;import com.metabuild.modules.admin.departments.application.*;import com.metabuild.shared.kernel.UuidV7Generator;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController
@RequestMapping("/api/depts") public final class DepartmentControllerContract {private final DepartmentService depts;private final UuidV7Generator ids;public DepartmentControllerContract(DepartmentService d,UuidV7Generator i){depts=d;ids=i;}@GetMapping @RequiresPermissions(codes = {"iam:user:view"}) public List<DepartmentView> tree(){return depts.tree();}@PostMapping @RequiresPermissions(codes = {"iam:dept:create"}) public DepartmentView create(@RequestBody CreateWrite w){if(w==null||w.name()==null||w.name().isBlank())throw invalid();return depts.create(ids.generate(),w.name(),w.parentId());}@PutMapping("/{id}") @RequiresPermissions(codes = {"iam:dept:update"}) public DepartmentView update(@PathVariable UUID id,@RequestBody UpdateWrite w){if(w==null)throw invalid();return depts.update(id,w.patch());}public record CreateWrite(String name,UUID parentId){}public static final class UpdateWrite{private boolean np,pp;private String name;private UUID parentId;public void setName(String n){np=true;name=n;}public void setParentId(UUID p){pp=true;parentId=p;}DepartmentPatch patch(){if(np&&(name==null||name.isBlank()))throw invalid();return new DepartmentPatch(np,name,pp,parentId);}}private static com.metabuild.shared.kernel.BadRequest invalid(){return new com.metabuild.shared.kernel.BadRequest(()->"request.validation.failed","Invalid department payload");}}
